#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;
bool fill(string* allrows, char dir, int x, int y, int fl, bool isfl, bool fill){
    if (dir != '0' && dir == '.'){
        if (isfl && !(y >= fl)){
            return 0;
        }
        if (fill){
            allrows[y].at(x) = '~';
        }
        return 1;
    }
    else{
        return 0;
    }
}
bool cond(int stream, int dis, int cond){
    if (stream + dis != cond){
        return 1;
    }
    else{
        return 0;
    }
}
void stream(string* allrows, int streamx, int streamy, int fl, int sizey, int sizex){
    char below;
    char left;
    char right;
    char leftdown;
    char rightdown;
    char above;
    if (cond(streamy, 1, sizey)){
       below = allrows[streamy + 1].at(streamx);
    }
    else{
        below = '0';
    }
    if (cond(streamy, -1, -1)){
        above = allrows[streamy - 1].at(streamx);
    }
    else{
        above = '0';
    }
    if (cond(streamx, -1, -1)){
        left = allrows[streamy].at(streamx - 1);
    }
    else{
        left = '0';
    }
    if (cond(streamx, 1, sizex)){
        right = allrows[streamy].at(streamx + 1);
    }
    else{
        right = '0';
    }
    if (below != '0'){
        if (left != '0'){
            leftdown = allrows[streamy + 1].at(streamx - 1);
        }
        if (right != '0'){
            rightdown = allrows[streamy + 1].at(streamx + 1);
        }
    }
    if (streamy >= fl){
        if (fill(allrows, left, streamx - 1, streamy, fl, 1, 1)){
            stream(allrows, streamx - 1, streamy, fl, sizey, sizex);
        }
        if (fill(allrows, right, streamx + 1, streamy, fl, 1, 1)){
            stream(allrows, streamx + 1, streamy, fl, sizey, sizex);
        }
        if (fill(allrows, above, streamx, streamy - 1, fl, 1, 1)){
            stream(allrows, streamx, streamy - 1, fl, sizey, sizex);
        }
        if (fill(allrows, below, streamx, streamy + 1, fl, 1, 1)){
            stream(allrows, streamx, streamy + 1, fl, sizey, sizex);
        }
    }
    else{
        switch (below){
            case '_':
            {
                if (fill(allrows, left, streamx - 1, streamy, fl, 0, 1)){
                    stream(allrows, streamx - 1, streamy, fl, sizey, sizex);
                }
                if (fill(allrows, right, streamx + 1, streamy, fl, 0, 1)){
                    stream(allrows, streamx + 1, streamy, fl, sizey, sizex);
                }
                break;
            }
            case '^':
            {
                if (fill(allrows, left, streamx - 1, streamy, fl, 0, 0)){
                    if (fill(allrows, leftdown, streamx - 1, streamy + 1, fl, 0, 1)){
                        stream(allrows, streamx - 1, streamy + 1, fl, sizey, sizex);
                    }
                }
                if (fill(allrows, right, streamx + 1, streamy, fl, 0, 0)){
                    if (fill(allrows, rightdown, streamx + 1, streamy + 1, fl, 0, 1)){
                        stream(allrows, streamx + 1, streamy + 1, fl, sizey, sizex);
                    }
                }
                break;
            }
            case '|':
            {
                bool wl = 0;
                if (allrows[streamy].at(streamx) != '!'){
                    if (fill(allrows, left, streamx - 1, streamy, fl, 0, 0)){
                        if (fill(allrows, leftdown, streamx - 1, streamy + 1, fl, 0, 1)){
                            stream(allrows, streamx - 1, streamy + 1, fl, sizey, sizex);
                        }
                        else{
                            wl = 1;
                        }
                    }
                    else{
                        wl = 1;
                    }
                    if (fill(allrows, right, streamx + 1, streamy, fl, 0, 0)){
                        if (fill(allrows, rightdown, streamx + 1, streamy + 1, fl, 0, 1)){
                            stream(allrows, streamx + 1, streamy + 1, fl, sizey, sizex);
                        }
                        else{
                            wl = 1;
                        }
                    }
                    else{
                        wl = 1;
                    }
                    if (wl){
                        allrows[streamy + 1].at(streamx) = '!';
                        stream(allrows, streamx, streamy + 1, fl, sizey, sizex);
                    }
                }
                else{
                    if (streamy + 1 < fl){
                        allrows[streamy + 1].at(streamx) = '!';
                    }
                    stream(allrows, streamx, streamy + 1, fl, sizey, sizex);
                }
                break;
            }
            case '/':
            {
                if (fill(allrows, leftdown, streamx - 1, streamy + 1, fl, 0, 1)){
                    stream(allrows, streamx - 1, streamy + 1, fl, sizey, sizex);
                }
                break;
            }
            case '\\':
            {
                if (fill(allrows, rightdown, streamx + 1, streamy + 1, fl, 0, 1)){
                    stream(allrows, streamx + 1, streamy + 1, fl, sizey, sizex);
                }
                break;
            }
            case '.':
            {
                fill(allrows, below, streamx, streamy + 1, fl, 0, 1);
                stream(allrows, streamx, streamy + 1, fl, sizey, sizex);
                break;
            }
            default:
            {
                break;
            }
        }
    }
}
int main()
{
    int w; int h; int r;
    cin >> w; cin.ignore();
    cin >> h; cin.ignore();
    cin >> r; cin.ignore();
    string allrows[h];
    for (int i = 0; i < h; i++) {
        getline(cin, allrows[i]);
    }
    for (int i = 0; i < h; ++i){
        for (int e = 0; e < w; ++e){
            if (allrows[i].at(e) == 'o'){
                stream(allrows, e, i, r, h, w);
            }
        }
    }

    for (int i = 0; i < h; ++i){
        cout << allrows[i] << endl;
    }
}

data.constraints:
{{0}} <= [[w]] <= {{30}}
{{0}} <= [[h]] <= {{30}}
{{0}} <= [[r]] <= [[h]]
There is going to be <<at least one water-generating cell>> {{o}} in the grid.
